var evidence = await FetchCapabilitiesWithFallbackAsync(handle, monitorId, cancellationToken);
if (evidence.IsPhysicalMonitorUnavailable) return Abandon(physical);
if (evidence.Capabilities == null && _knownGoodStore.TryGet(monitorId, out var cached))
    evidence = VcpDiscoveryEvidence.FromCached(cached, degraded: true);
if (evidence.Capabilities == null) return Abandon(physical);
return BuildMonitorFromPhysical(physical, info, monitorId, evidence);

var currentKeys = result.Select(m => (EdidId(m.Id), Normalize(m.Name))).ToHashSet();
var retained = existing.Where(e => !IsCurrent(e) && IsRecentOrHidden(e));
foreach (var group in retained.GroupBy(e => (EdidId(e.Id), Normalize(e.Name))))
    MergeIntoCurrentOnly(group, result, prefer: CurrentThenNewest);

foreach (var monitor in monitors)
{
    var vm = new MonitorViewModel(monitor, _monitorManager, this);
    ApplyFeatureVisibility(vm, settings);
    vm.SetDegradedState(monitor.IsDegraded);
    Monitors.Add(vm);
}
